begin;
create or replace function public.consultar_historico_gestao(p_oficina uuid,p_inicio date,p_fim date,p_tipo text default '',p_busca text default '',p_pagina integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$declare itens jsonb;total bigint;begin
 perform private.exigir_gestao(p_oficina,'reports');if p_inicio is null or p_fim is null or p_inicio>p_fim or p_fim-p_inicio>366 then raise exception 'Escolha um período de até 367 dias.' using errcode='22023';end if;
 with eventos as(
 select a.id::text id,a.criado_em data,'auditoria'::text origem,a.tipo_entidade tipo,case a.acao when 'saved' then 'Lançamento financeiro salvo' when 'paid' then 'Pagamento registrado' when 'reversed' then 'Pagamento estornado' when 'cancelled' then 'Lançamento cancelado' when 'costs_reviewed' then 'Custos conferidos' when 'os_generated' then 'Receita de OS gerada' when 'transfer_reversed' then 'Transferência estornada' when 'configuracoes_atualizadas' then 'Configurações da oficina atualizadas' when 'salvar_produto' then 'Produto de estoque atualizado' when 'cliente.cadastrado' then 'Cliente cadastrado' when 'cliente.editado' then 'Cliente atualizado' when 'cliente.arquivado' then 'Cliente arquivado' when 'cliente.restaurado' then 'Cliente restaurado' when 'orcamento.criado' then 'Orçamento criado' when 'orcamento.editado' then 'Orçamento atualizado' when 'orcamento.emitido' then 'Orçamento emitido' when 'orcamento.revisado' then 'Nova versão de orçamento' when 'orcamento.cancelado' then 'Orçamento cancelado' when 'orcamento.approved' then 'Orçamento aprovado' when 'orcamento.declined' then 'Orçamento recusado' else replace(a.acao,'_',' ') end descricao,a.usuario_autor_id autor,a.entidade_id entidade,null::text numero from public.registros_auditoria a where a.oficina_id=p_oficina
 union all select h.id::text,h.ocorrido_em,'os','ordem_servico',h.descricao,h.usuario_autor_id,h.ordem_servico_id,w.numero::text from public.historico_ordem_servico h join public.ordens_servico w on w.id=h.ordem_servico_id and w.oficina_id=h.oficina_id where h.oficina_id=p_oficina
 union all select m.id::text,m.criado_em,'estoque','estoque',m.tipo||': '||c.descricao||' · '||m.motivo,m.criado_por,m.item_catalogo_id,null from public.movimentacoes_estoque m join public.itens_catalogo c on c.id=m.item_catalogo_id and c.oficina_id=m.oficina_id where m.oficina_id=p_oficina
 ),filtrados as(select * from eventos where (data at time zone 'America/Sao_Paulo')::date between p_inicio and p_fim and (p_tipo='' or tipo=p_tipo) and translate(lower(concat(descricao,' ',numero)),'áàâãéêíóôõúüç','aaaaeeiooouuc') like '%'||translate(lower(left(p_busca,120)),'áàâãéêíóôõúüç','aaaaeeiooouuc')||'%')
 select (select count(*) from filtrados),(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select * from filtrados order by data desc,origem,id limit 30 offset greatest(p_pagina,0)*30)x) into total,itens;
 return jsonb_build_object('itens',itens,'total',total);end $$;

notify pgrst,'reload schema';commit;
